/* generated by scripts/build_arch_units_int.py
 *
 * The RV64 integer arch-opcodes, each written as the language's own integer
 * operators over unsigned 64-bit values.  Two things here are not a plain
 * operator:
 *
 *   au_sra / au_sraw   an arithmetic right shift written out in UNSIGNED bit
 *                      operations, so it does not lean on C's
 *                      implementation-defined `>>` of a negative value, and
 *                      so all four languages compute it the same way.
 *   au_divrem_u        restoring long division.  NO `/` or `%` of the host
 *                      language appears anywhere in this file, because RISC-V
 *                      div/divu/rem/remu do not trap: b == 0 gives an
 *                      all-ones quotient and the dividend back as the
 *                      remainder, and the signed most-negative over minus one
 *                      gives the most-negative back with a zero remainder.
 *
 * Every shift count is masked to the width RISC-V actually uses (6 bits for
 * the doubleword forms, 5 for the word forms) before it reaches a `<<` or
 * `>>`, so no shift here is ever undefined in C or C++.
 */
#ifndef AU_INT_HPP
#define AU_INT_HPP

#include <cstdint>

namespace archunits {

#define AU_ONES UINT64_C(0xffffffffffffffff)
#define AU_MIN64 UINT64_C(0x8000000000000000)

inline uint64_t au_b2u(bool b) { return b ? UINT64_C(1) : UINT64_C(0); }
inline uint64_t au_sext32(uint64_t x)
{
    return (uint64_t)(int64_t)(int32_t)(uint32_t)x;
}
inline uint64_t au_add(uint64_t a, uint64_t b) { return a + b; }
inline uint64_t au_sub(uint64_t a, uint64_t b) { return a - b; }
inline uint64_t au_and(uint64_t a, uint64_t b) { return a & b; }
inline uint64_t au_or(uint64_t a, uint64_t b)  { return a | b; }
inline uint64_t au_xor(uint64_t a, uint64_t b) { return a ^ b; }
inline uint64_t au_andn(uint64_t a, uint64_t b) { return a & ~b; }
inline uint64_t au_mul(uint64_t a, uint64_t b) { return a * b; }
inline uint64_t au_addw(uint64_t a, uint64_t b) { return au_sext32(a + b); }
inline uint64_t au_subw(uint64_t a, uint64_t b) { return au_sext32(a - b); }
inline uint64_t au_mulw(uint64_t a, uint64_t b) { return au_sext32(a * b); }
inline uint64_t au_sll(uint64_t a, uint64_t s) { return a << (s & 63); }
inline uint64_t au_srl(uint64_t a, uint64_t s) { return a >> (s & 63); }
inline uint64_t au_sra(uint64_t a, uint64_t n)
{
    uint64_t s = n & 63;
    uint64_t r = a >> s;
    uint64_t m = UINT64_C(0) - (a >> 63);        /* all ones if negative */
    return r | ((m << (63 - s)) << 1);           /* s == 0 shifts it out */
}
inline uint64_t au_sllw(uint64_t a, uint64_t n)
{
    return au_sext32((a << (n & 31)) & UINT64_C(0xffffffff));
}
inline uint64_t au_srlw(uint64_t a, uint64_t n)
{
    return au_sext32((a & UINT64_C(0xffffffff)) >> (n & 31));
}
inline uint64_t au_sraw(uint64_t a, uint64_t n)
{
    uint64_t s = n & 31;
    uint64_t r = (a & UINT64_C(0xffffffff)) >> s;
    uint64_t m = UINT64_C(0) - ((a >> 31) & UINT64_C(1));
    r |= ((m << (31 - s)) << 1) & UINT64_C(0xffffffff);
    return au_sext32(r);
}
inline uint64_t au_slt(uint64_t a, uint64_t b)
{
    return au_b2u((int64_t)a < (int64_t)b);
}
inline uint64_t au_sltu(uint64_t a, uint64_t b) { return au_b2u(a < b); }
inline uint64_t au_eqz(uint64_t a) { return au_b2u(a == 0); }
inline uint64_t au_nez(uint64_t a) { return au_b2u(a != 0); }
inline uint64_t au_ltz(uint64_t a) { return au_b2u((int64_t)a < 0); }
inline uint64_t au_gez(uint64_t a) { return au_b2u((int64_t)a >= 0); }
inline uint64_t au_czeqz(uint64_t v, uint64_t c) { return c == 0 ? 0 : v; }
inline uint64_t au_cznez(uint64_t v, uint64_t c) { return c != 0 ? 0 : v; }

/* restoring long division: 64 steps, no / and no % */
inline void au_divrem_u(uint64_t a, uint64_t b, uint64_t *qo, uint64_t *ro)
{
    uint64_t q = 0, r = 0;
    int i;
    for (i = 63; i >= 0; i--) {
        uint64_t carry = r >> 63;
        r = (r << 1) | ((a >> i) & UINT64_C(1));
        if (carry != 0 || r >= b) { r -= b; q |= UINT64_C(1) << i; }
    }
    *qo = q; *ro = r;
}
inline uint64_t au_divu(uint64_t a, uint64_t b)
{
    uint64_t q, r;
    if (b == 0) return AU_ONES;                  /* RISC-V divu by zero */
    au_divrem_u(a, b, &q, &r);
    return q;
}
inline uint64_t au_remu(uint64_t a, uint64_t b)
{
    uint64_t q, r;
    if (b == 0) return a;                        /* RISC-V remu by zero */
    au_divrem_u(a, b, &q, &r);
    return r;
}
inline uint64_t au_div(uint64_t a, uint64_t b)
{
    uint64_t na, nb, q, r;
    if (b == 0) return AU_ONES;
    if (a == AU_MIN64 && b == AU_ONES) return AU_MIN64;
    na = a >> 63; nb = b >> 63;
    au_divrem_u(na ? (UINT64_C(0) - a) : a, nb ? (UINT64_C(0) - b) : b,
                &q, &r);
    return (na ^ nb) ? (UINT64_C(0) - q) : q;
}
inline uint64_t au_rem(uint64_t a, uint64_t b)
{
    uint64_t na, nb, q, r;
    if (b == 0) return a;
    if (a == AU_MIN64 && b == AU_ONES) return 0;
    na = a >> 63; nb = b >> 63;
    au_divrem_u(na ? (UINT64_C(0) - a) : a, nb ? (UINT64_C(0) - b) : b,
                &q, &r);
    return na ? (UINT64_C(0) - r) : r;           /* sign of the dividend */
}
inline uint64_t au_divw(uint64_t a, uint64_t b)
{
    return au_sext32(au_div(au_sext32(a), au_sext32(b)));
}
inline uint64_t au_remw(uint64_t a, uint64_t b)
{
    return au_sext32(au_rem(au_sext32(a), au_sext32(b)));
}
inline uint64_t au_divuw(uint64_t a, uint64_t b)
{
    return au_sext32(au_divu(a & UINT64_C(0xffffffff),
                             b & UINT64_C(0xffffffff)));
}
inline uint64_t au_remuw(uint64_t a, uint64_t b)
{
    return au_sext32(au_remu(a & UINT64_C(0xffffffff),
                             b & UINT64_C(0xffffffff)));
}

}  // namespace archunits

#endif
